    function getStudentProfile(identifier) {
      if (!identifier) identifier = '67080200501';
      const clean = String(identifier).trim().toLowerCase();

      if (studentDirectory[clean]) {
        return studentDirectory[clean];
      }

      const numMatch = clean.match(/\d{9,11}/);
      if (numMatch && studentDirectory[numMatch[0]]) {
        return studentDirectory[numMatch[0]];
      }

      const foundByEmail = Object.values(studentDirectory).find(s =>
        s.email.toLowerCase() === clean ||
        s.email.toLowerCase().startsWith(clean) ||
        clean.includes(s.email.toLowerCase().split('@')[0])
      );
      if (foundByEmail) {
        return foundByEmail;
      }

      const foundByName = Object.values(studentDirectory).find(s =>
        s.fullName.toLowerCase() === clean ||
        s.shortName.toLowerCase() === clean ||
        s.fullName.toLowerCase().includes(clean)
      );
      if (foundByName) {
        return foundByName;
      }

      const fallbackId = numMatch ? numMatch[0] : (clean.includes('@') ? '67080200501' : (clean || '67080200501'));
      if (studentDirectory[fallbackId]) {
        return studentDirectory[fallbackId];
      }

      const generatedParts = fallbackId.length >= 3 ? fallbackId.slice(-3) : fallbackId;
      return {
        id: fallbackId,
        fullName: `Student ${fallbackId}`,
        shortName: `Student ${generatedParts}`,
        email: `student.${fallbackId}@mail.kmutt.ac.th`,
        initials: 'ST',
        major: 'Applied Computer Science - Multimedia',
        dept: 'Department of Applied Computer Science - Multimedia'
      };
    }

    function getCurrentStudent() {
      const sid = localStorage.getItem('atht_student_id') || '67080200501';
      return getStudentProfile(sid);
    }

