    function getTeacherAssignedCourseCodes(teacher = null) {
      const t = teacher || getCurrentTeacher();
      if (t && Array.isArray(t.courses) && t.courses.length > 0) {
        const valid = t.courses.filter(code => Boolean(coursesCatalog[code]));
        if (valid.length > 0) return valid;
      }
      return Object.keys(coursesCatalog || {});
    }

    function getTeacherProfile(identifier) {
      if (!identifier) identifier = 'suripong.ler';
      const clean = String(identifier).trim().toLowerCase();

      if (teacherDirectory[clean]) {
        return teacherDirectory[clean];
      }

      const foundByEmail = Object.values(teacherDirectory).find(t =>
        t.email.toLowerCase() === clean ||
        t.email.toLowerCase().startsWith(clean) ||
        clean === t.email.toLowerCase().split('@')[0] ||
        (clean.includes('teacher@') && t.id === 'nuttapong.pra')
      );
      if (foundByEmail) {
        return foundByEmail;
      }

      const foundByName = Object.values(teacherDirectory).find(t =>
        t.fullName.toLowerCase().includes(clean) ||
        t.shortName.toLowerCase().includes(clean) ||
        clean.includes(t.fullName.toLowerCase().split(' ').pop()) ||
        clean.includes('suripong') && t.id === 'suripong.ler' ||
        clean.includes('nuttapong') && t.id === 'nuttapong.pra' ||
        clean.includes('akek') && t.id === 'akek.pat'
      );
      if (foundByName) {
        return foundByName;
      }

      const foundByCode = Object.values(teacherDirectory).find(t =>
        t.facultyCode.toLowerCase() === clean
      );
      if (foundByCode) {
        return foundByCode;
      }

      if (clean.includes('@') && !clean.includes('mail.kmutt.ac.th') && !clean.match(/\d{9,11}/)) {
        const username = clean.split('@')[0];
        const parts = username.split(/[._-]/);
        const first = parts[0].charAt(0).toUpperCase() + parts[0].slice(1);
        const last = parts.length > 1 ? parts[1].charAt(0).toUpperCase() + parts[1].slice(1) : '';
        const initials = (first.charAt(0) + (last ? last.charAt(0) : 'T')).toUpperCase();
        return {
          id: username,
          fullName: last ? `Prof. ${first} ${last}` : `Prof. ${first}`,
          shortName: last ? `Prof. ${first} ${last.charAt(0)}.` : `Prof. ${first}`,
          initials: initials,
          email: clean,
          facultyCode: `FAC-CMM-${Math.floor(100 + Math.random() * 899)}`,
          title: 'Course Instructor',
          dept: 'Department of Applied Computer Science - Multimedia',
          faculty: 'Faculty of Industrial Education and Technology',
          specialization: 'Applied Computer Science - Multimedia',
          courses: []
        };
      }

      return teacherDirectory['suripong.ler'];
    }

    function getCurrentTeacher() {
      const tid = localStorage.getItem('atht_teacher_id') || 'suripong.ler';
      return getTeacherProfile(tid);
    }

    function switchTeacherAccount(newId) {
      if (!newId) return;
      localStorage.setItem('atht_teacher_id', newId);
      const teacher = getTeacherProfile(newId);
      updateBreadcrumbUI(currentScreen);
      if (currentScreen === 'teacher-dashboard') {
        renderTeacherDashboard();
      }
      openUserProfileModal();
      alertMessage(`Switched active instructor to: ${teacher.fullName} (${teacher.email})`);
    }

    function openUserProfileModal() {
      const modal = document.getElementById('modalUserProfile');
      if (!modal) return;
      const isTeacher = currentUserRole === 'teacher';
      const isAdmin = currentUserRole === 'admin';
      const student = getCurrentStudent();
      const isThai = currentLanguage === 'th';

      const avatarEl = document.getElementById('userProfileModalAvatar');
      const iconEl = document.getElementById('userProfileModalIcon');
      const titleEl = document.getElementById('userProfileModalTitle');
      const idLabelEl = document.getElementById('userProfileModalIdLabel');
      const nameEl = document.getElementById('userProfileModalName');
      const roleBadgeEl = document.getElementById('userProfileModalRoleBadge');
      const idEl = document.getElementById('userProfileModalId');
      const emailEl = document.getElementById('userProfileModalEmail');
      const mailtoEl = document.getElementById('userProfileModalMailto');
      const deptEl = document.getElementById('userProfileModalDept');
      const majorEl = document.getElementById('userProfileModalMajor');
      const switcherContainer = document.getElementById('userProfileModalSwitcherContainer');

      if (isAdmin) {
        if (iconEl) iconEl.innerHTML = '<span class="text-base">🛡️</span>';
        if (titleEl) titleEl.innerText = isThai ? 'ข้อมูลผู้ดูแลระบบ' : 'Admin Profile';
        if (idLabelEl) idLabelEl.innerText = isThai ? 'รหัสผู้ดูแลระบบ' : 'Admin ID';
        if (avatarEl) avatarEl.innerText = 'AD';
        if (nameEl) nameEl.innerText = 'System Administrator';
        if (roleBadgeEl) roleBadgeEl.innerText = isThai ? 'ผู้ดูแลระบบหลัก • มจธ.' : 'Super Admin • KMUTT Portal';
        if (idEl) idEl.innerText = 'ADM-KMUTT-001';
        if (emailEl) emailEl.innerText = 'admin@kmutt.ac.th';
        if (mailtoEl) mailtoEl.href = 'mailto:admin@kmutt.ac.th';
        if (deptEl) deptEl.innerText = 'Department of Applied Computer Science - Multimedia';
        if (majorEl) majorEl.innerText = 'System Directory & Access Control Management';
        if (switcherContainer) {
          switcherContainer.classList.remove('hidden');
          const labelEl = switcherContainer.querySelector('label');
          if (labelEl) labelEl.innerText = isThai ? 'สลับมุมมองพอร์ทัล (Admin / Teacher / Student)' : 'Quick Role Switch (Admin / Teacher / Student)';
          const selectEl = document.getElementById('userProfileStudentSelect');
          if (selectEl) {
            selectEl.onchange = (e) => {
              closeUserProfileModal();
              quickLoginAs(e.target.value);
            };
            selectEl.innerHTML = `
              <option value="admin" selected>🛡️ System Administrator (admin@kmutt.ac.th)</option>
              <option value="teacher">👨‍🏫 Teacher Portal (Prof. Suripong L.)</option>
              <option value="student">🎓 Student Portal (Chonchanok S. - 67080200501)</option>
            `;
          }
        }
      } else if (isTeacher) {
        if (iconEl) iconEl.innerHTML = '<span class="text-base">👨‍🏫</span>';
        if (titleEl) titleEl.innerText = isThai ? 'ข้อมูลอาจารย์ผู้สอน' : 'Teacher Profile';
        if (idLabelEl) idLabelEl.innerText = isThai ? 'รหัสอาจารย์ผู้สอน' : 'Teacher ID';
        const teacher = getCurrentTeacher();
        if (avatarEl) avatarEl.innerText = teacher.initials;
        if (nameEl) nameEl.innerText = teacher.fullName;
        if (roleBadgeEl) roleBadgeEl.innerText = isThai ? `อาจารย์ผู้สอน • ${teacher.specialization}` : `Course Instructor • ${teacher.specialization}`;
        if (idEl) idEl.innerText = teacher.facultyCode;
        if (emailEl) emailEl.innerText = teacher.email;
        if (mailtoEl) mailtoEl.href = `mailto:${teacher.email}`;
        if (deptEl) deptEl.innerText = teacher.dept;
        if (majorEl) majorEl.innerText = `${teacher.faculty} (${teacher.specialization})`;

        if (switcherContainer) {
          switcherContainer.classList.remove('hidden');
          const labelEl = switcherContainer.querySelector('label');
          if (labelEl) labelEl.innerText = isThai ? 'สลับ / ทดสอบบัญชีอาจารย์ หรือเข้าหน้า Admin' : 'Switch Instructor Account / Open Admin Portal';
          const selectEl = document.getElementById('userProfileStudentSelect');
          if (selectEl) {
            selectEl.onchange = (e) => {
              if (e.target.value === '__ADMIN__') {
                closeUserProfileModal();
                quickLoginAs('admin');
              } else {
                switchTeacherAccount(e.target.value);
              }
            };
            selectEl.innerHTML = Object.values(teacherDirectory).map(t =>
              `<option value="${t.id}" ${t.id === teacher.id ? 'selected' : ''}>👨‍🏫 ${escapeHtml(t.fullName)} (${t.email})</option>`
            ).join('') + `<option value="__ADMIN__">🛡️ Switch to System Admin Portal (Manage Users)</option>`;
          }
        }
      } else {
        if (iconEl) iconEl.innerHTML = '<img src="student-icon.png" alt="Student" class="w-5 h-5 object-contain" />';
        if (titleEl) titleEl.innerText = isThai ? 'ข้อมูลนักศึกษา' : 'Student Profile';
        if (idLabelEl) idLabelEl.innerText = isThai ? 'รหัสนักศึกษา' : 'Student ID';
        if (avatarEl) avatarEl.innerText = student.initials;
        if (nameEl) nameEl.innerText = student.fullName;
        if (roleBadgeEl) roleBadgeEl.innerText = isThai ? 'นักศึกษาปริญญาตรี • สื่อมัลติมีเดีย' : 'Undergraduate Student • Multimedia';
        if (idEl) idEl.innerText = student.id;
        if (emailEl) emailEl.innerText = student.email;
        if (mailtoEl) mailtoEl.href = `mailto:${student.email}`;
        if (deptEl) deptEl.innerText = student.dept;
        if (majorEl) majorEl.innerText = student.major;

        if (switcherContainer) {
          switcherContainer.classList.remove('hidden');
          const labelEl = switcherContainer.querySelector('label');
          if (labelEl) labelEl.innerText = isThai ? `สลับรหัสนักศึกษา (${Object.keys(studentDirectory).length} คน) หรือเข้าหน้า Admin` : `Switch Student ID (${Object.keys(studentDirectory).length} Students) / Admin`;
          const selectEl = document.getElementById('userProfileStudentSelect');
          if (selectEl) {
            selectEl.onchange = (e) => {
              if (e.target.value === '__ADMIN__') {
                closeUserProfileModal();
                quickLoginAs('admin');
              } else {
                switchStudentAccount(e.target.value);
              }
            };
            selectEl.innerHTML = `<option value="__ADMIN__">🛡️ Switch to System Admin Portal (Manage Users)</option>` + Object.values(studentDirectory).map(s =>
              `<option value="${s.id}" ${s.id === student.id ? 'selected' : ''}>🎓 ${s.id} - ${escapeHtml(s.fullName)} (${s.email})</option>`
            ).join('');
          }
        }
      }

      modal.classList.remove('hidden');
    }

    function closeUserProfileModal() {
      const modal = document.getElementById('modalUserProfile');
      if (modal) modal.classList.add('hidden');
    }

    function switchStudentAccount(newId) {
      if (!newId) return;
      localStorage.setItem('atht_student_id', newId);
      const student = getStudentProfile(newId);
      updateBreadcrumbUI(currentScreen);
      if (currentScreen === 'dashboard') {
        renderDashboardCourses();
      }
      openUserProfileModal();
      alertMessage(`Switched active student to: ${student.fullName} (${student.id})`);
    }

    function copyStudentEmail() {
      const emailEl = document.getElementById('userProfileModalEmail');
      if (!emailEl) return;
      const emailText = emailEl.innerText.trim();
      navigator.clipboard.writeText(emailText).then(() => {
        alertMessage(currentLanguage === 'th' ? 'คัดลอกอีเมลเรียบร้อยแล้ว!' : 'KMUTT Email copied to clipboard!');
      }).catch(() => {
        alertMessage(emailText);
      });
    }

